package ec.edu.scli.reservas.application.service;
import ec.edu.scli.reservas.client.*; import ec.edu.scli.reservas.client.dto.*; import ec.edu.scli.reservas.domain.model.*; import ec.edu.scli.reservas.domain.port.out.*; import ec.edu.scli.reservas.infrastructure.persistence.entity.*; import ec.edu.scli.reservas.infrastructure.persistence.repository.*; import ec.edu.scli.reservas.presentation.dto.request.*; import org.junit.jupiter.api.*; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class SolicitudCambioPlanificacionServiceTest {
 private SolicitudCambioPlanificacionJpaRepository solicitudes=mock(SolicitudCambioPlanificacionJpaRepository.class); private RevisionSolicitudCambioJpaRepository revisiones=mock(RevisionSolicitudCambioJpaRepository.class); private PlanificacionAgregadaJpaRepository planes=mock(PlanificacionAgregadaJpaRepository.class); private PlanificacionJpaRepository bloques=mock(PlanificacionJpaRepository.class); private ActorActualPort actores=mock(ActorActualPort.class); private ContextoInstitucionalPort contextos=mock(ContextoInstitucionalPort.class); private PoliticaAmbitoLaboratorio ambito=mock(PoliticaAmbitoLaboratorio.class); private AcademicoLaboratoriosClient academico=mock(AcademicoLaboratoriosClient.class); private UsuariosClient usuarios=mock(UsuariosClient.class); private NotificacionService notificaciones=mock(NotificacionService.class); private PlanificacionAgregadaService disponibilidad=mock(PlanificacionAgregadaService.class); private SolicitudCambioPlanificacionService service=new SolicitudCambioPlanificacionService(solicitudes,revisiones,planes,bloques,actores,contextos,ambito,academico,usuarios,notificaciones,disponibilidad);
 @Test void solicitudPendienteConservaBloqueOriginalYProtegePisosOrigenDestino(){UUID perfil=UUID.randomUUID(),carrera=UUID.randomUUID(),planId=UUID.randomUUID(),bloqueId=UUID.randomUUID(),periodo=UUID.randomUUID(),origen=UUID.randomUUID(),destino=UUID.randomUUID(),piso1=UUID.randomUUID(),piso2=UUID.randomUUID();var plan=new PlanificacionAgregadaJpaEntity();plan.setId(planId);plan.setCarreraId(carrera);plan.setPeriodoId(periodo);plan.setEstado(EstadoPlanificacionAgregada.APROBADA);var bloque=new PlanificacionJpaEntity();bloque.setId(bloqueId);bloque.setPlanificacionId(planId);bloque.setLaboratorioId(origen);bloque.setDiaSemana("LUNES");bloque.setHoraInicio(LocalTime.of(8,0));bloque.setHoraFin(LocalTime.of(9,0));when(actores.obtener()).thenReturn(new ActorAutenticado(perfil,Set.of("ROLE_COORDINADOR")));when(contextos.obtenerPorPerfilId(perfil)).thenReturn(new ContextoInstitucional(true,true,false,false,false,null,List.of(carrera)));when(planes.findById(planId)).thenReturn(Optional.of(plan));when(bloques.findById(bloqueId)).thenReturn(Optional.of(bloque));when(academico.obtenerPeriodo(periodo)).thenReturn(new PeriodoExternoResponse(periodo,"P","P",LocalDate.now().minusDays(1),LocalDate.now().plusDays(10),"ACTIVO","PPA","REGULAR PPA",1));when(academico.obtenerLaboratorio(origen)).thenReturn(new LaboratorioExternoResponse(origen,piso1,true,true,"DISPONIBLE",20));when(academico.obtenerLaboratorio(destino)).thenReturn(new LaboratorioExternoResponse(destino,piso2,true,true,"DISPONIBLE",20));when(usuarios.obtenerAdministradoresPorPiso(any())).thenReturn(List.of(UUID.randomUUID()));when(solicitudes.saveAndFlush(any())).thenAnswer(i->{SolicitudCambioPlanificacionJpaEntity s=i.getArgument(0);s.setId(UUID.randomUUID());return s;});when(revisiones.findBySolicitudId(any())).thenReturn(List.of());var out=service.crear(planId,new CrearSolicitudCambioRequest(bloqueId,TipoSolicitudCambio.LABORATORIO,"Mantenimiento imprevisto",destino,null,null,null,null));assertThat(out.estado()).isEqualTo("PENDIENTE");assertThat(bloque.getLaboratorioId()).isEqualTo(origen);verify(revisiones,times(2)).save(any());verify(bloques,never()).save(any());}
}
